function reportProduct(Database $db, Business $business, array $p): array {
    $snap=$business->stockSnapshot($p);
    return ['id'=>(int)$p['id'],'code'=>$p['code'],'name'=>$p['name'],'type'=>$p['type'],'unit'=>$p['unit'],'stock'=>(int)$p['stock'],'minStock'=>(int)$p['min_stock'],'usageLocation'=>$p['usage_location'],'shelf'=>$p['shelf'],'description'=>$p['description'],'inCustody'=>$snap['inCustody'],'inRepair'=>$snap['inRepair'],'available'=>$snap['available'],'status'=>$business->getStockStatus($p)];
}
