 if($path==='/api/reports/custom'){$limit=min(max((int)($q['limit']??500),1),2000);$include=($q['includeVoided']??'')==='1';$where=['1=1'];$args=[];if(!$include)$where[]="t.status='معتبر'";if(($q['startDate']??'')!==''){$where[]='t.date>=?';$args[]=reportDate($q['startDate'],'تاریخ شروع');}if(($q['endDate']??'')!==''){$where[]='t.date<=?';$args[]=reportDate($q['endDate'],'تاریخ پایان');}if(($q['requestingUnit']??'')!==''){$where[]='t.requesting_unit=?';$args[]=(string)$q['requestingUnit'];}if(($q['type']??'')!==''&&($q['type']??'')!=='all'){$where[]='t.type=?';$args[]=(string)$q['type'];}if(($q['usageLocation']??'')!==''){$where[]='p.usage_location=?';$args[]=(string)$q['usageLocation'];}if(($q['receiver']??'')!==''){$term='%'.mb_strtolower(trim((string)$q['receiver']),'UTF-8').'%';$where[]="(LOWER(COALESCE(t.receiver,'')) LIKE ? OR LOWER(COALESCE(t.returned_by,'')) LIKE ?)";array_push($args,$term,$term);} $rows=$db->all('SELECT t.*,p.name product_name,p.usage_location product_usage_location FROM transactions t LEFT JOIN products p ON p.id=t.product_id WHERE '.implode(' AND ',$where).' ORDER BY t.id DESC LIMIT '.$limit,$args);$results=array_map(fn($t)=>['docNumber'=>$t['doc_number'],'date'=>$t['date'],'productName'=>$t['product_name'],'type'=>$t['type'],'quantity'=>(int)$t['quantity'],'requestingUnit'=>$t['requesting_unit'],'party'=>$t['receiver']?:($t['returned_by']?:($t['source']??null)),'usageLocation'=>$t['product_usage_location'],'voided'=>($t['status']??'معتبر')==='باطل'],$rows);jsonResponse(['results'=>$results,'limit'=>$limit,'truncated'=>count($results)===$limit]);}
